describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discount results against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 100
        new FixedAmountDiscountPolicy(200), // 200
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // Both see 1000: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so total is just the other child
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ]);
      // 10% of 1000 = 100, fixed 50 => 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
        new PercentageDiscountPolicy(10), // 10% of 900 = 90
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      // total discount = 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("second policy sees reduced subtotal", () => {
      const policies = [
        new FixedAmountDiscountPolicy(500), // 500 off 1000 → remaining 500
        new PercentageDiscountPolicy(50), // 50% of 500 = 250
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering matters in chain mode", () => {
      const policiesA = [
        new FixedAmountDiscountPolicy(200),
        new PercentageDiscountPolicy(10),
      ];
      const policiesB = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const compositeA = new CompositeDiscountPolicy(policiesA, "chain");
      const compositeB = new CompositeDiscountPolicy(policiesB, "chain");
      // A: 200 off 1000 → 800, then 10% of 800 = 80 → total 280
      // B: 10% of 1000 = 100 → 900, then 200 off 900 → total 300
      expect(compositeA.computeDiscountCents(1000)).toBe(280);
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("caps each step at remaining subtotal", () => {
      const policies = [
        new FixedAmountDiscountPolicy(800),
        new FixedAmountDiscountPolicy(800), // only 200 remaining
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
