    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(productA, 1); // subtotal 1000, discount 100 → discounted 900
    const totals = cart.totals();
    // shipping receives the snapshot lines and discounted subtotal
    expect(mockShipping.computeShippingCents).toHaveBeenCalled();
    const callArgs = (mockShipping.computeShippingCents as ReturnType<typeof vi.fn>).mock.calls[0]!;
    expect(callArgs[1]).toBe(900); // discounted subtotal
    expect(totals.shippingCents).toBe(500);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-10),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(productA, 1);
